f="/_nuxt/SectionWrapper.DwKxBi0v.css" crossorigin><script integrity="sha384-UCvw6Ra0Nxm64UPlcc9KCL3+C6CZl2BPerjA4QiULIS33rtcnYSKjhdGVD27bKmZ" type="module" src="404-not-found.html" crossorigin></script><meta hid="description" name="description" content="{{ asset('We continually work to develop and implement arrangements to minimize resource consumption, emissions and waste generated by our activities.') }}"><meta name="format-detection" content="{{ asset('telephone=no') }}"><link rel="icon" type="image/x-icon" href="/favicon.ico"><link rel="canonical" href="/environment-policy"><script type="text/javascript" src="{{ asset('clients/clients.js') }}"></script><script type="text/javascript" src="{{ asset('d52c969eb9aa.edge.sdk.awswaf.com/d52c969eb9aa/3aa3b8a4ac7b/challenge.js') }}" defer></script>
